SRC_FILES = {'src/__init__.py': '', 'src/data/__init__.py': '', 'src/data/load_data.py': '"""Load data ADIKARA 2025 (prediksi gagal bayar pinjaman)."""\nfrom __future__ import annotations\n\nimport os\nfrom pathlib import Path\n\nimport pandas as pd\n\nTARGET = "status_gagal_bayar"\nID = "id_transaksi"\nCATEGORICAL = ["provinsi", "jenis_pinjaman", "status_peminjam", "sektor_usaha", "pendidikan", "jenis_jaminan"]\nNUMERIC = ["jumlah_pinjaman", "total_pengembalian", "durasi_hari", "porsi_pengembalian_lender"]\n\n\ndef find_data_dir(local: str | Path = "../data/raw") -> Path:\n    """Folder yang berisi train.csv kompetisi ini (di /kaggle/input, ikuti symlink)."""\n    for root, _, files in os.walk("/kaggle/input", followlinks=True):\n        if {"train.csv", "test.csv"} <= set(files):\n            if TARGET in pd.read_csv(Path(root) / "train.csv", nrows=1).columns:\n                return Path(root)\n    return Path(local)\n\n\ndef load(data_dir: str | Path) -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame]:\n    d = Path(data_dir)\n    sample = next(d.glob("sample_submission*.csv"))\n    return pd.read_csv(d / "train.csv"), pd.read_csv(d / "test.csv"), pd.read_csv(sample)\n', 'src/features/__init__.py': '', 'src/features/build_features.py': '"""Fitur turunan untuk prediksi gagal bayar, dikelompokkan agar bisa diuji satu per satu (ablation)."""\nfrom __future__ import annotations\n\nimport numpy as np\nimport pandas as pd\n\nfrom src.data.load_data import CATEGORICAL, NUMERIC\n\nGROUPS = {\n    "A. rasio pengembalian": ["markup", "markup_dari_lender"],\n    "B. porsi lender": ["porsi_lender", "lender_per_pinjaman"],\n    "C. waktu pencairan": ["bulan_ke", "hari_dalam_minggu"],\n    "D. pola data kosong": ["n_kosong"],\n}\n\n\ndef base_frame(train: pd.DataFrame, test: pd.DataFrame) -> tuple[pd.DataFrame, pd.DataFrame]:\n    """Fitur mentah, dengan kategori memakai satu kamus untuk train dan test."""\n    Xtr, Xte = train[NUMERIC + CATEGORICAL].copy(), test[NUMERIC + CATEGORICAL].copy()\n    for c in CATEGORICAL:\n        cats = sorted(set(Xtr[c].dropna()) | set(Xte[c].dropna()))\n        Xtr[c] = pd.Categorical(Xtr[c], categories=cats)\n        Xte[c] = pd.Categorical(Xte[c], categories=cats)\n    return Xtr, Xte\n\n\ndef derived(d: pd.DataFrame, typical_share: dict[str, float]) -> pd.DataFrame:\n    out = pd.DataFrame(index=d.index)\n    loan = d.jumlah_pinjaman.replace(0, np.nan)\n    out["markup"] = d.total_pengembalian / loan\n    # jika total pengembalian kosong: perkirakan dari porsi lender dibagi porsi lender yang umum untuk jenis pinjamannya\n    share = d.jenis_pinjaman.map(typical_share).astype(float)\n    out["markup_dari_lender"] = d.porsi_pengembalian_lender / share / loan\n    out["porsi_lender"] = d.porsi_pengembalian_lender / d.total_pengembalian.replace(0, np.nan)\n    out["lender_per_pinjaman"] = d.porsi_pengembalian_lender / loan\n    t = pd.to_datetime(d.tanggal_pencairan)\n    out["bulan_ke"] = (t.dt.year - 2022) * 12 + t.dt.month\n    out["hari_dalam_minggu"] = t.dt.dayofweek\n    out["n_kosong"] = d[NUMERIC + ["jenis_pinjaman"]].isna().sum(axis=1)\n    return out\n\n\ndef typical_lender_share(train: pd.DataFrame) -> dict[str, float]:\n    s = (train.porsi_pengembalian_lender / train.total_pengembalian).round(2)\n    s = s[(s > 0) & (s < 1)]\n    return s.groupby(train.jenis_pinjaman).agg(lambda v: v.mode().iloc[0]).to_dict()\n\n\ndef build(base: pd.DataFrame, raw: pd.DataFrame, share: dict[str, float], groups: list[str] | None = None) -> pd.DataFrame:\n    groups = list(GROUPS) if groups is None else groups\n    der = derived(raw, share)\n    cols = [c for g in groups for c in GROUPS[g]]\n    return pd.concat([base, der[cols]], axis=1)\n', 'src/models/__init__.py': '', 'src/models/train_model.py': '"""Stratified K-Fold berulang, LightGBM, dan pemilihan ambang untuk macro F1."""\nfrom __future__ import annotations\n\nimport lightgbm as lgb\nimport numpy as np\nfrom sklearn.metrics import f1_score\nfrom sklearn.model_selection import StratifiedKFold\n\nLGB_PARAMS = dict(n_estimators=500, learning_rate=0.03, num_leaves=15, min_child_samples=20, subsample=0.8,\n                  subsample_freq=1, colsample_bytree=0.8)\nTHRESHOLDS = np.round(np.arange(0.05, 0.951, 0.01), 2)\n\n\ndef lgb_model(seed: int = 0, **kw):\n    return lgb.LGBMClassifier(**{**LGB_PARAMS, **kw}, random_state=seed, verbose=-1)\n\n\ndef cv_predict(make_model, X, y, seeds=range(5), n_splits: int = 5) -> np.ndarray:\n    """Probabilitas out-of-fold untuk tiap seed. Hasil: array (n_seed, n_baris)."""\n    y = np.asarray(y)\n    out = np.zeros((len(list(seeds)), len(y)))\n    for i, s in enumerate(seeds):\n        for trn, val in StratifiedKFold(n_splits, shuffle=True, random_state=s).split(X, y):\n            out[i, val] = make_model(s).fit(X.iloc[trn], y[trn]).predict_proba(X.iloc[val])[:, 1]\n    return out\n\n\ndef f1_curve(y, p) -> np.ndarray:\n    return np.array([f1_score(y, p >= t, average="macro") for t in THRESHOLDS])\n\n\ndef best_threshold(y, p) -> tuple[float, float]:\n    c = f1_curve(y, p)\n    i = int(np.argmax(c))\n    return float(THRESHOLDS[i]), float(c[i])\n\n\ndef macro_f1_by_seed(oof: np.ndarray, y, mask=None) -> tuple[list[float], list[float]]:\n    """Macro F1 terbaik (ambang dipilih per seed) dan ambangnya, pada baris `mask`."""\n    y = np.asarray(y)\n    mask = np.ones(len(y), bool) if mask is None else np.asarray(mask)\n    res = [best_threshold(y[mask], p[mask]) for p in np.atleast_2d(oof)]\n    return [r[1] for r in res], [r[0] for r in res]\n', 'src/visualization/__init__.py': '', 'src/visualization/plots.py': '"""Gaya grafik yang konsisten dan ramah buta warna (palet Okabe–Ito)."""\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nimport matplotlib.pyplot as plt\nimport matplotlib.ticker as mtick\nimport seaborn as sns\n\nPALETTE = {"normal": "#0072B2", "fraud": "#D55E00", "accent": "#009E73", "neutral": "#8C8C8C"}\n\n\ndef set_style() -> None:\n    sns.set_theme(style="whitegrid", context="notebook", palette="colorblind")\n    plt.rcParams.update({"figure.dpi": 110, "axes.titleweight": "bold", "axes.titlesize": 12})\n\n\ndef save_fig(fig_dir: Path, name: str) -> None:\n    """Rapikan layout, simpan PNG ke `fig_dir`, lalu tampilkan."""\n    plt.tight_layout()\n    plt.savefig(Path(fig_dir) / f"{name}.png", dpi=130, bbox_inches="tight")\n    plt.show()\n\n\ndef pct_axis(ax, decimals: int = 1, axis: str = "y") -> None:\n    fmt = mtick.PercentFormatter(1, decimals=decimals)\n    (ax.yaxis if axis == "y" else ax.xaxis).set_major_formatter(fmt)\n\n\ndef ref_line(ax, value: float, label: str = "rata-rata") -> None:\n    ax.axhline(value, color=PALETTE["neutral"], ls="--", lw=1.2, label=label)\n'}
NOTEBOOK = json.loads('{\n "cells": [\n  {\n   "cell_type": "markdown",\n   "id": "e7e09b48",\n   "metadata": {},\n   "source": [\n    "# Memprediksi Gagal Bayar Pinjaman UMKM: Sinyal Terkuat Ada di Rasio Pengembalian\\n",\n    "\\n",\n    "| | |\\n",\n    "| --- | --- |\\n",\n    "| **Kompetisi** | [ADIKARA 2025: Indonesian Credit Score](https://www.kaggle.com/competitions/adikara-2025-indonesia-kredit-macet) (Fakultas Informatika Telkom University, Kaggle, Desember 2025) |\\n",\n    "| **Tujuan** | Memprediksi `status_gagal_bayar` (1 = gagal bayar) untuk transaksi pinjaman digital (metrik macro F1) |\\n",\n    "| **Data** | 20.012 transaksi berlabel dan 5.003 transaksi uji, 11 atribut pinjaman dan peminjam |\\n",\n    "| **Penulis** | Fauzan Ahsanudin Alfikri · [Kaggle: fauzan2](https://www.kaggle.com/fauzan2) |\\n",\n    "| **Tanggal** | Disusun ulang November 2026, menggantikan notebook kompetisi Desember 2025 |\\n",\n    "| **Lingkungan** | Dijalankan penuh di Kaggle (CPU) |\\n",\n    "\\n",\n    "**Pertanyaan penelitian.** Atribut apa yang paling membedakan pinjaman yang gagal bayar, dan bagaimana mengubah\\n",\n    "probabilitas model menjadi label 0/1 yang memaksimalkan macro F1?\\n",\n    "\\n",\n    "**Ringkasan temuan.**\\n",\n    "- **Rasio pengembalian** (total pengembalian dibagi pokok pinjaman) adalah sinyal paling kuat: AUC 0,984 sendirian. Pinjaman dengan rasio ≤ 1,01 hampir tidak pernah gagal bayar, sedangkan rasio di atas 1,2 gagal bayar 92%.\\n",\n    "- Atribut peminjam seperti provinsi, sektor usaha, pendidikan, dan jaminan hampir tidak berpengaruh (4,7–5,5% gagal bayar di semua kategori). Yang berbeda hanya peminjam baru (41%) dan jenis pinjaman di luar modal usaha.\\n",\n    "- Data kosong di train (24% baris) jauh lebih banyak daripada di test (7%). Validasi utama dihitung pada baris yang total pengembaliannya terisi, karena itulah kondisi 99% baris test.\\n",\n    "- LightGBM dengan rasio pengembalian dan waktu pencairan mencapai **macro F1 OOF 0,947** (atribut mentah saja 0,851). Late submission: public **0,9563**, private **0,9450**; submission tim saat kompetisi mencapai private tertinggi 0,9471 (peringkat akhir 6 dari 49).\\n",\n    "- Tanpa total pengembalian dan porsi lender (atribut yang kemungkinan baru diketahui setelah pinjaman berjalan), macro F1 turun ke 0,667.\\n",\n    "\\n",\n    "**Alur:** 1. Setup → 2. Memahami data → 3. EDA → 4. Preprocessing dan desain validasi → 5. Baseline →\\n",\n    "6. Feature engineering dan ablation → 7. Ambang keputusan → 8. Interpretasi → 9. Submission → 10. Kesimpulan"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "ea603560",\n   "metadata": {},\n   "source": [\n    "## 1. Setup\\n",\n    "\\n",\n    "Semua import, parameter, dan path ada di sel ini. Fitur turunan ada di `src/features`, dan cross-validation serta pemilihan\\n",\n    "ambang ada di `src/models`."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "b8fea59a",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "import os\\n",\n    "import shutil\\n",\n    "import sys\\n",\n    "import time\\n",\n    "import warnings\\n",\n    "from importlib.metadata import version\\n",\n    "from pathlib import Path\\n",\n    "\\n",\n    "import numpy as np\\n",\n    "import pandas as pd\\n",\n    "import matplotlib.pyplot as plt\\n",\n    "import seaborn as sns\\n",\n    "from sklearn.compose import make_column_transformer\\n",\n    "from sklearn.impute import SimpleImputer\\n",\n    "from sklearn.linear_model import LogisticRegression\\n",\n    "from sklearn.metrics import confusion_matrix, f1_score, roc_auc_score\\n",\n    "from sklearn.model_selection import StratifiedKFold, cross_val_predict\\n",\n    "from sklearn.pipeline import make_pipeline\\n",\n    "from sklearn.preprocessing import OneHotEncoder, StandardScaler\\n",\n    "\\n",\n    "SRC_ROOT = Path.cwd().parent\\n",\n    "for r, _, f in os.walk(\\"/kaggle/input\\", followlinks=True):\\n",\n    "    if Path(r).name == \\"features\\" and \\"build_features.py\\" in f:\\n",\n    "        pkg = Path(r).parent\\n",\n    "        if pkg.name == \\"src\\":\\n",\n    "            SRC_ROOT = pkg.parent\\n",\n    "        else:\\n",\n    "            SRC_ROOT = Path(\\"/tmp/project\\")\\n",\n    "            shutil.copytree(pkg, SRC_ROOT / \\"src\\", dirs_exist_ok=True)\\n",\n    "        break\\n",\n    "sys.path.insert(0, str(SRC_ROOT))\\n",\n    "from src.data.load_data import CATEGORICAL, ID, NUMERIC, TARGET, find_data_dir, load\\n",\n    "from src.features.build_features import GROUPS, base_frame, build, derived, typical_lender_share\\n",\n    "from src.models.train_model import THRESHOLDS, best_threshold, cv_predict, f1_curve, lgb_model, macro_f1_by_seed\\n",\n    "from src.visualization.plots import PALETTE, pct_axis, save_fig, set_style\\n",\n    "\\n",\n    "# ── Parameter eksperimen\\n",\n    "SEEDS = range(5)                 # Stratified 5-Fold diulang dengan 5 seed\\n",\n    "\\n",\n    "# ── Path\\n",\n    "DATA_DIR = find_data_dir(local=\\"../data/raw\\")\\n",\n    "OUT_DIR = Path(\\"/kaggle/working\\") if Path(\\"/kaggle/working\\").exists() else Path(\\"../reports\\")\\n",\n    "FIG_DIR = OUT_DIR / \\"figures\\"\\n",\n    "FIG_DIR.mkdir(parents=True, exist_ok=True)\\n",\n    "\\n",\n    "warnings.filterwarnings(\\"ignore\\")\\n",\n    "set_style()\\n",\n    "C1, C2, C3, CN = PALETTE[\\"normal\\"], PALETTE[\\"fraud\\"], PALETTE[\\"accent\\"], PALETTE[\\"neutral\\"]\\n",\n    "T0 = time.time()\\n",\n    "print(\\"DATA_DIR:\\", DATA_DIR, \\"| OUT_DIR:\\", OUT_DIR)"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "97296be1",\n   "metadata": {},\n   "source": [\n    "## 2. Memahami data\\n",\n    "\\n",\n    "Setiap baris adalah satu pinjaman: tanggal pencairan, provinsi, jenis pinjaman, status peminjam (baru atau berulang),\\n",\n    "jumlah pinjaman, total pengembalian, durasi, porsi pengembalian untuk lender, sektor usaha, pendidikan, dan jenis jaminan."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "2ef3c6a7",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "train, test, sample = load(DATA_DIR)\\n",\n    "y = train[TARGET].values\\n",\n    "print(f\\"Train: {train.shape} | Test: {test.shape} | gagal bayar: {y.mean():.2%} ({y.sum():,} transaksi)\\")\\n",\n    "miss = pd.DataFrame({\\"kosong train\\": train.isna().mean(), \\"kosong test\\": test.isna().mean()})\\n",\n    "display(train.head(3))\\n",\n    "miss[miss.sum(1) > 0].style.format(\\"{:.1%}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "3a4be833",\n   "metadata": {},\n   "source": [\n    "**Temuan.** 20.012 transaksi latih dengan 5,03% gagal bayar (1.006 transaksi), jadi kelasnya sangat tidak seimbang. Empat kolom punya nilai kosong. Yang penting: total pengembalian dan porsi lender kosong di sekitar 10% baris train, tetapi hanya sekitar 1% baris test."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "05eb0302",\n   "metadata": {},\n   "source": [\n    "## 3. Exploratory Data Analysis\\n",\n    "\\n",\n    "### 3.1 Atribut kategori: hanya dua yang berbeda"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "e4b6f4ba",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "fig, axes = plt.subplots(2, 3, figsize=(17, 8))\\n",\n    "for a, c in zip(axes.flat, CATEGORICAL):\\n",\n    "    g = train.groupby(train[c].fillna(\\"(kosong)\\"))[TARGET].agg([\\"mean\\", \\"size\\"]).sort_values(\\"mean\\")\\n",\n    "    a.barh(g.index.astype(str), g[\\"mean\\"], color=[C2 if v > 2 * y.mean() else C1 for v in g[\\"mean\\"]])\\n",\n    "    a.axvline(y.mean(), color=CN, ls=\\"--\\", lw=1)\\n",\n    "    for i, (m, n) in enumerate(zip(g[\\"mean\\"], g[\\"size\\"])):\\n",\n    "        a.text(m, i, f\\" {m:.0%} (n={n:,})\\", va=\\"center\\", fontsize=8)\\n",\n    "    pct_axis(a, 0, axis=\\"x\\"); a.set(title=c, xlabel=\\"proporsi gagal bayar\\")\\n",\n    "save_fig(FIG_DIR, \\"01_categorical\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "333459f2",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Provinsi, sektor usaha, pendidikan, dan jenis jaminan semuanya berada di sekitar rata-rata 5%, jadi atribut profil peminjam ini hampir tidak membawa informasi. Dua atribut yang berbeda: **peminjam baru** gagal bayar 41% (tetapi hanya 221 transaksi), dan jenis pinjaman di luar modal usaha (investasi 19%, mikro UKM 21%, multiguna 29%, konsumtif 83%). Modal usaha mendominasi data dan hanya 3–4% gagal bayar."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "94cfcd48",\n   "metadata": {},\n   "source": [\n    "### 3.2 Rasio pengembalian: total pengembalian dibagi jumlah pinjaman\\n",\n    "\\n",\n    "Pinjaman yang lancar dikembalikan hampir sebesar pokoknya. Grafik berikut melihat apa yang terjadi jika total\\n",\n    "pengembalian jauh di atas pokok."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "ce3f5586",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "markup = train.total_pengembalian / train.jumlah_pinjaman.replace(0, np.nan)\\n",\n    "bins = [0, 1, 1.01, 1.03, 1.05, 1.1, 1.2, 1.5, np.inf]\\n",\n    "mb = train.groupby(pd.cut(markup, bins, right=True, include_lowest=True), observed=True)[TARGET].agg([\\"mean\\", \\"size\\"])\\n",\n    "fig, ax = plt.subplots(1, 2, figsize=(16, 4.6))\\n",\n    "ax[0].bar([str(i) for i in mb.index], mb[\\"mean\\"], color=C2)\\n",\n    "for i, (m, n) in enumerate(zip(mb[\\"mean\\"], mb[\\"size\\"])):\\n",\n    "    ax[0].text(i, m + 0.01, f\\"{m:.0%}\\\\nn={n:,}\\", ha=\\"center\\", fontsize=8)\\n",\n    "pct_axis(ax[0], 0); ax[0].set(xlabel=\\"rasio pengembalian (total / pokok)\\", ylabel=\\"proporsi gagal bayar\\", title=\\"Gagal bayar per rentang rasio pengembalian\\")\\n",\n    "ax[0].tick_params(axis=\\"x\\", rotation=30)\\n",\n    "for k, col, lab in [(0, C1, \\"lancar\\"), (1, C2, \\"gagal bayar\\")]:\\n",\n    "    ax[1].hist(markup[(y == k)].clip(0.95, 2), bins=60, alpha=0.6, density=True, color=col, label=lab)\\n",\n    "ax[1].set(yscale=\\"log\\", xlabel=\\"rasio pengembalian (dipotong di 2)\\", ylabel=\\"densitas (log)\\", title=\\"Distribusi rasio per kelas\\"); ax[1].legend()\\n",\n    "save_fig(FIG_DIR, \\"02_markup\\")\\n",\n    "print(f\\"AUC rasio pengembalian saja (baris terisi): {roc_auc_score(y[markup.notna()], markup.dropna()):.4f} | AUC jumlah pinjaman saja: {roc_auc_score(y, train.jumlah_pinjaman):.4f}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "2d02fe7b",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Ini temuan utama. Pinjaman dengan rasio pengembalian sampai 1,01 **tidak satu pun** gagal bayar (8.871 transaksi), rasio 1,05–1,1 gagal bayar 16%, rasio 1,1–1,2 sebanyak 60%, dan di atas 1,2 sebanyak 92%. Rasio pengembalian sendirian memberi AUC 0,984, sementara jumlah pinjaman hanya 0,618. Kemungkinan besar total pengembalian sudah memuat denda atau bunga keterlambatan, sehingga nilainya baru diketahui setelah pinjaman berjalan. Untuk kompetisi atribut ini sah dipakai, tetapi untuk credit scoring sungguhan saat pengajuan, atribut ini tidak tersedia (lihat Keterbatasan)."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "8ffa0a8f",\n   "metadata": {},\n   "source": [\n    "### 3.3 Durasi, waktu pencairan, dan porsi lender"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "dcf3f051",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "t = pd.to_datetime(train.tanggal_pencairan)\\n",\n    "q = train.groupby(t.dt.to_period(\\"Q\\"))[TARGET].agg([\\"mean\\", \\"size\\"])\\n",\n    "fig, ax = plt.subplots(1, 3, figsize=(18, 4.5))\\n",\n    "db = train.groupby(pd.cut(train.durasi_hari, [-2, 0, 6, 7, 14, 30, 60, 2000]), observed=True)[TARGET].agg([\\"mean\\", \\"size\\"])\\n",\n    "ax[0].bar([str(i) for i in db.index], db[\\"mean\\"], color=C1); pct_axis(ax[0], 0)\\n",\n    "ax[0].set(xlabel=\\"durasi (hari)\\", ylabel=\\"proporsi gagal bayar\\", title=\\"Gagal bayar per durasi\\"); ax[0].tick_params(axis=\\"x\\", rotation=30)\\n",\n    "ax2 = ax[1].twinx()\\n",\n    "ax2.bar(q.index.astype(str), q[\\"size\\"], color=CN, alpha=0.35)\\n",\n    "ax[1].plot(q.index.astype(str), q[\\"mean\\"], marker=\\"o\\", color=C2); ax[1].set_zorder(ax2.get_zorder() + 1); ax[1].patch.set_visible(False)\\n",\n    "pct_axis(ax[1], 0); ax[1].set(ylabel=\\"proporsi gagal bayar\\", title=\\"Per kuartal pencairan (batang = jumlah)\\"); ax[1].tick_params(axis=\\"x\\", rotation=60)\\n",\n    "ax2.set_ylabel(\\"jumlah transaksi\\")\\n",\n    "share = (train.porsi_pengembalian_lender / train.total_pengembalian.replace(0, np.nan)).round(2)\\n",\n    "top = share.value_counts().head(8).index\\n",\n    "sb = train[share.isin(top)].groupby(share[share.isin(top)])[TARGET].agg([\\"mean\\", \\"size\\"])\\n",\n    "ax[2].bar(sb.index.astype(str), sb[\\"mean\\"], color=C3); pct_axis(ax[2], 0)\\n",\n    "ax[2].set(xlabel=\\"porsi lender (8 nilai tersering)\\", ylabel=\\"proporsi gagal bayar\\", title=\\"Gagal bayar per porsi lender\\")\\n",\n    "save_fig(FIG_DIR, \\"03_duration_time_share\\")\\n",\n    "q.T.style.format(\\"{:.3f}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "dabeba26",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Durasi 7 hari adalah standar (17.795 transaksi, 3,5% gagal bayar), dan risiko naik untuk durasi lebih panjang, sampai 57% untuk lebih dari 60 hari. Waktu pencairan juga berpengaruh: 2023Q3–Q4 memuat 91% transaksi dengan gagal bayar sekitar 3%, sedangkan kuartal lain gagal bayar 13–77%. Porsi lender 0,13–0,2 berisiko lebih tinggi karena nilai itu milik jenis pinjaman non-modal usaha, bukan karena porsinya sendiri."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "4185e53e",\n   "metadata": {},\n   "source": [\n    "### 3.4 Data kosong di train dan test tidak sama"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "6fe19d84",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "mt = train.total_pengembalian.isna()\\n",\n    "print(f\\"Total pengembalian kosong: train {mt.mean():.1%}, test {test.total_pengembalian.isna().mean():.1%}\\")\\n",\n    "print(f\\"Gagal bayar saat total pengembalian kosong: {y[mt].mean():.2%} vs terisi {y[~mt].mean():.2%}\\")\\n",\n    "Xb_tr, Xb_te = base_frame(train, test)\\n",\n    "adv_X = pd.concat([Xb_tr, Xb_te], ignore_index=True)\\n",\n    "adv_y = np.r_[np.zeros(len(train)), np.ones(len(test))]\\n",\n    "cv = StratifiedKFold(5, shuffle=True, random_state=0)\\n",\n    "adv_p = cross_val_predict(lgb_model(0, n_estimators=200), adv_X, adv_y, cv=cv, method=\\"predict_proba\\")[:, 1]\\n",\n    "full = adv_X.notna().all(axis=1).values\\n",\n    "adv_p2 = cross_val_predict(lgb_model(0, n_estimators=200), adv_X[full], adv_y[full], cv=cv, method=\\"predict_proba\\")[:, 1]\\n",\n    "print(f\\"Adversarial AUC train vs test: {roc_auc_score(adv_y, adv_p):.3f} | hanya baris tanpa nilai kosong: {roc_auc_score(adv_y[full], adv_p2):.3f}\\")\\n",\n    "miss_tr = train[NUMERIC + [\'jenis_pinjaman\']].isna().any(axis=1)\\n",\n    "print(f\\"Baris train dengan minimal satu nilai kosong: {miss_tr.mean():.1%} | test: {test[NUMERIC + [\'jenis_pinjaman\']].isna().any(axis=1).mean():.1%}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "c69f8572",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Saat total pengembalian kosong, gagal bayar 5,4%, hampir sama dengan saat terisi (5,0%). Jadi nilai kosong ini disisipkan acak dan tidak membawa informasi label. Adversarial AUC 0,607 seluruhnya berasal dari pola kosong: pada baris tanpa nilai kosong AUC turun ke 0,524. Konsekuensinya, skor cross-validation pada semua baris **meremehkan** skor test, karena di test rasio pengembalian hampir selalu bisa dihitung."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "1e29a4a2",\n   "metadata": {},\n   "source": [\n    "## 4. Preprocessing dan desain validasi\\n",\n    "\\n",\n    "Keputusan yang diambil dari EDA:\\n",\n    "\\n",\n    "- **Nilai kosong dibiarkan** untuk ditangani LightGBM, karena polanya tidak informatif terhadap label.\\n",\n    "- **Kategori memakai satu kamus** untuk train dan test.\\n",\n    "- **Validasi meniru test.** Total pengembalian kosong di 10% baris train tetapi hanya 1% baris test. Model tetap dilatih\\n",\n    "  pada semua baris, tetapi skor utama dihitung pada **baris train yang total pengembaliannya terisi**, karena itulah kondisi\\n",\n    "  hampir semua baris test. Skor pada semua baris juga dilaporkan.\\n",\n    "- **Ambang dipilih dari OOF.** Macro F1 butuh label 0/1, jadi ambang probabilitas dipilih per seed dari prediksi\\n",\n    "  out-of-fold, bukan ditetapkan 0,5."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "ac46a76a",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "SHARE = typical_lender_share(train)\\n",\n    "TEST_LIKE = train.total_pengembalian.notna().values\\n",\n    "print(\\"Porsi lender yang umum per jenis pinjaman:\\", SHARE)\\n",\n    "print(f\\"Baris \'seperti test\': {TEST_LIKE.sum():,} dari {len(train):,}\\")\\n",\n    "RESULTS, OOF = {}, {}\\n",\n    "\\n",\n    "def record(name, oof):\\n",\n    "    f_tl, thr = macro_f1_by_seed(oof, y, TEST_LIKE)\\n",\n    "    f_all, _ = macro_f1_by_seed(oof, y)\\n",\n    "    o = np.atleast_2d(oof)\\n",\n    "    OOF[name] = o.mean(0)\\n",\n    "    RESULTS[name] = {\\"macro F1 (seperti test)\\": np.mean(f_tl), \\"std antar seed\\": np.std(f_tl), \\"macro F1 (semua baris)\\": np.mean(f_all),\\n",\n    "                     \\"AUC\\": np.mean([roc_auc_score(y, p) for p in o]), \\"ambang\\": np.mean(thr)}\\n",\n    "    return f\\"{name}: macro F1 seperti test {np.mean(f_tl):.4f} ± {np.std(f_tl):.4f} | semua baris {np.mean(f_all):.4f} | ambang {np.mean(thr):.2f}\\""\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "6a8ca254",\n   "metadata": {},\n   "source": [\n    "## 5. Baseline\\n",\n    "\\n",\n    "Semua skor adalah hasil out-of-fold dari Stratified 5-Fold yang diulang dengan 5 seed.\\n",\n    "\\n",\n    "- **Aturan satu atribut:** gagal bayar jika status peminjam = baru atau jenis pinjaman = konsumtif.\\n",\n    "- **Regresi logistik:** atribut mentah, one-hot untuk kategori, median untuk nilai kosong, log untuk nominal uang.\\n",\n    "- **LightGBM:** atribut mentah tanpa fitur turunan."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "2fd39488",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "rule = ((train.status_peminjam == \\"Peminjam_Baru\\") | (train.jenis_pinjaman == \\"Konsumtif\\")).astype(float).values\\n",\n    "print(record(\\"aturan: peminjam baru atau konsumtif\\", np.tile(rule, (len(SEEDS), 1))))\\n",\n    "Xlr = train[NUMERIC + CATEGORICAL].copy()\\n",\n    "for c in [\\"jumlah_pinjaman\\", \\"total_pengembalian\\", \\"porsi_pengembalian_lender\\"]:\\n",\n    "    Xlr[c] = np.log1p(Xlr[c].clip(lower=0))\\n",\n    "def logreg(seed):\\n",\n    "    pre = make_column_transformer((make_pipeline(SimpleImputer(strategy=\\"median\\"), StandardScaler()), NUMERIC),\\n",\n    "                                  (make_pipeline(SimpleImputer(strategy=\\"most_frequent\\"), OneHotEncoder(handle_unknown=\\"ignore\\")), CATEGORICAL))\\n",\n    "    return make_pipeline(pre, LogisticRegression(max_iter=3000, C=1.0))\\n",\n    "print(record(\\"regresi logistik, atribut mentah\\", cv_predict(logreg, Xlr, y, SEEDS)))\\n",\n    "print(record(\\"LightGBM, atribut mentah\\", cv_predict(lgb_model, Xb_tr, y, SEEDS)))"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "bfb176c9",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Aturan \\"peminjam baru atau konsumtif\\" hanya mencapai macro F1 0,581. Regresi logistik pada atribut mentah 0,658, karena hubungan yang penting adalah rasio dua kolom, bukan kolom itu sendiri. LightGBM pada atribut mentah sudah 0,851: pohon bisa mendekati rasio dengan memotong total pengembalian dan jumlah pinjaman berulang kali, tetapi tidak sempurna."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "d11dd03d",\n   "metadata": {},\n   "source": [\n    "## 6. Feature engineering dan ablation\\n",\n    "\\n",\n    "Empat kelompok fitur turunan, masing-masing dari temuan EDA, ditambahkan satu per satu:\\n",\n    "\\n",\n    "| Kelompok | Fitur | Dasar dari EDA |\\n",\n    "| --- | --- | --- |\\n",\n    "| A. rasio pengembalian | total / pokok, dan perkiraannya dari porsi lender jika total kosong | bagian 3.2 |\\n",\n    "| B. porsi lender | porsi lender terhadap total dan terhadap pokok | bagian 3.3 |\\n",\n    "| C. waktu pencairan | bulan ke-, hari dalam minggu | bagian 3.3 |\\n",\n    "| D. pola data kosong | jumlah atribut kosong per baris | bagian 3.4 |"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "8642590e",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "ABL = []\\n",\n    "steps = []\\n",\n    "for g in GROUPS:\\n",\n    "    steps.append(g)\\n",\n    "    name = \\"LightGBM + \\" + \\", \\".join(s.split(\\".\\")[0] for s in steps)\\n",\n    "    X = build(Xb_tr, train, SHARE, steps)\\n",\n    "    print(record(name, cv_predict(lgb_model, X, y, SEEDS)))\\n",\n    "    ABL.append((g, name, X.shape[1]))\\n",\n    "abl = pd.DataFrame([{\\"langkah\\": \\"atribut mentah\\", \\"fitur\\": Xb_tr.shape[1], **RESULTS[\\"LightGBM, atribut mentah\\"]}] +\\n",\n    "                   [{\\"langkah\\": \\"+ \\" + g, \\"fitur\\": k, **RESULTS[n]} for g, n, k in ABL])\\n",\n    "abl[\\"perubahan\\"] = abl[\\"macro F1 (seperti test)\\"].diff()\\n",\n    "fig, ax = plt.subplots(figsize=(11, 4.3))\\n",\n    "ax.errorbar(abl.langkah, abl[\\"macro F1 (seperti test)\\"], yerr=abl[\\"std antar seed\\"], marker=\\"o\\", color=C2, capsize=4, label=\\"baris seperti test\\")\\n",\n    "ax.plot(abl.langkah, abl[\\"macro F1 (semua baris)\\"], marker=\\"s\\", color=C1, ls=\\"--\\", label=\\"semua baris\\")\\n",\n    "ax.set(ylabel=\\"macro F1 OOF\\", title=\\"Ablation kumulatif kelompok fitur\\"); ax.legend(); ax.tick_params(axis=\\"x\\", rotation=15)\\n",\n    "save_fig(FIG_DIR, \\"04_ablation\\")\\n",\n    "abl.style.format({c: \\"{:.4f}\\" for c in [\\"macro F1 (seperti test)\\", \\"std antar seed\\", \\"macro F1 (semua baris)\\", \\"AUC\\", \\"perubahan\\"]} | {\\"ambang\\": \\"{:.2f}\\"})"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "a82fec93",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Menambahkan rasio pengembalian (A) menaikkan macro F1 dari 0,851 menjadi **0,940**, lompatan terbesar di seluruh notebook. Porsi lender (B) tidak membantu (−0,0004). Waktu pencairan (C) menambah 0,007, lebih besar dari variasi antar seed. Pola data kosong (D) tidak menambah apa pun, sesuai temuan bahwa nilai kosong disisipkan acak. Pola yang sama terlihat pada skor semua baris, yang selalu sekitar 0,015 lebih rendah."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "8b30a676",\n   "metadata": {},\n   "source": [\n    "### 6.1 Set fitur akhir\\n",\n    "\\n",\n    "Kelompok dipertahankan jika menaikkan macro F1 (seperti test) lebih dari satu standar deviasi antar seed dibanding langkah\\n",\n    "sebelumnya; kelompok lain dibuang."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "a34e71bd",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "KEEP = []\\n",\n    "prev = RESULTS[\\"LightGBM, atribut mentah\\"][\\"macro F1 (seperti test)\\"]\\n",\n    "for g, n, _ in ABL:\\n",\n    "    gain = RESULTS[n][\\"macro F1 (seperti test)\\"] - prev\\n",\n    "    if gain > RESULTS[n][\\"std antar seed\\"]:\\n",\n    "        KEEP.append(g)\\n",\n    "    prev = RESULTS[n][\\"macro F1 (seperti test)\\"]\\n",\n    "KEEP = KEEP or [\\"A. rasio pengembalian\\"]\\n",\n    "FINAL_NAME = \\"LightGBM akhir: \\" + \\", \\".join(s.split(\\".\\")[0] for s in KEEP)\\n",\n    "X_final = build(Xb_tr, train, SHARE, KEEP)\\n",\n    "OOF_FINAL = cv_predict(lgb_model, X_final, y, SEEDS)\\n",\n    "print(\\"Kelompok dipertahankan:\\", KEEP)\\n",\n    "print(record(FINAL_NAME, OOF_FINAL))"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "704e4939",\n   "metadata": {},\n   "source": [\n    "### 6.2 Tanpa total pengembalian: model saat pengajuan pinjaman\\n",\n    "\\n",\n    "Total pengembalian dan porsi lender kemungkinan baru diketahui setelah pinjaman berjalan. Untuk melihat seberapa banyak\\n",\n    "informasi tersisa saat pengajuan, model dilatih tanpa kedua kolom itu (tetap dengan waktu pencairan)."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "776ee316",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "X_pre = build(Xb_tr.drop(columns=[\\"total_pengembalian\\", \\"porsi_pengembalian_lender\\"]), train, SHARE, [\\"C. waktu pencairan\\"])\\n",\n    "print(record(\\"LightGBM tanpa total pengembalian & porsi lender\\", cv_predict(lgb_model, X_pre, y, SEEDS)))"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "22054afc",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Tanpa total pengembalian dan porsi lender, macro F1 turun dari 0,947 menjadi **0,667** (AUC 0,796), hanya sedikit di atas regresi logistik. Jadi hampir seluruh kemampuan model datang dari atribut yang kemungkinan baru diketahui setelah pinjaman berjalan. Untuk keputusan pemberian pinjaman, atribut yang tersedia saat pengajuan hanya cukup untuk penyaringan kasar."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "07709e36",\n   "metadata": {},\n   "source": [\n    "## 7. Ambang keputusan untuk macro F1"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "25876ccf",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "p_fin = OOF[FINAL_NAME]\\n",\n    "curve_tl, curve_all = f1_curve(y[TEST_LIKE], p_fin[TEST_LIKE]), f1_curve(y, p_fin)\\n",\n    "THR, F1_TL = best_threshold(y[TEST_LIKE], p_fin[TEST_LIKE])\\n",\n    "fig, ax = plt.subplots(1, 2, figsize=(15, 4.5))\\n",\n    "ax[0].plot(THRESHOLDS, curve_tl, color=C2, label=\\"baris seperti test\\")\\n",\n    "ax[0].plot(THRESHOLDS, curve_all, color=C1, ls=\\"--\\", label=\\"semua baris\\")\\n",\n    "ax[0].axvline(THR, color=\\"black\\", lw=0.8, ls=\\":\\", label=f\\"ambang terpilih {THR:.2f}\\")\\n",\n    "ax[0].axvline(0.5, color=CN, lw=0.8, ls=\\"--\\", label=\\"0,5\\")\\n",\n    "ax[0].set(xlabel=\\"ambang probabilitas\\", ylabel=\\"macro F1 OOF\\", title=\\"Macro F1 terhadap ambang\\"); ax[0].legend(fontsize=8)\\n",\n    "cm = confusion_matrix(y[TEST_LIKE], p_fin[TEST_LIKE] >= THR)\\n",\n    "sns.heatmap(cm, annot=True, fmt=\\",d\\", cmap=\\"Blues\\", cbar=False, ax=ax[1], xticklabels=[\\"prediksi lancar\\", \\"prediksi gagal\\"], yticklabels=[\\"lancar\\", \\"gagal bayar\\"])\\n",\n    "ax[1].set(title=f\\"Confusion matrix OOF (seperti test), ambang {THR:.2f}\\")\\n",\n    "save_fig(FIG_DIR, \\"05_threshold\\")\\n",\n    "print(f\\"Macro F1 pada ambang 0,5: {f1_score(y[TEST_LIKE], p_fin[TEST_LIKE] >= 0.5, average=\'macro\'):.4f} | pada ambang {THR:.2f}: {F1_TL:.4f}\\")\\n",\n    "print(f\\"F1 kelas gagal bayar: {f1_score(y[TEST_LIKE], p_fin[TEST_LIKE] >= THR):.4f} | F1 kelas lancar: {f1_score(1 - y[TEST_LIKE], p_fin[TEST_LIKE] < THR):.4f}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "1cccecbc",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Kurva macro F1 cukup datar di sekitar ambang 0,3–0,55, jadi pilihan ambang tidak sensitif. Ambang terpilih 0,42 memberi 0,9487 pada OOF gabungan, hanya sedikit di atas ambang 0,5 (0,9476). F1 kelas gagal bayar 0,903 dan kelas lancar 0,995; macro F1 terutama ditentukan oleh kelas gagal bayar."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "09eb72cb",\n   "metadata": {},\n   "source": [\n    "## 8. Interpretasi\\n",\n    "\\n",\n    "### 8.1 Fitur terpenting"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "60204582",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "m = lgb_model(0).fit(X_final, y)\\n",\n    "imp = pd.Series(m.booster_.feature_importance(\\"gain\\"), index=X_final.columns)\\n",\n    "imp = (imp / imp.sum()).sort_values()\\n",\n    "fig, ax = plt.subplots(1, 2, figsize=(16, 4.8))\\n",\n    "ax[0].barh(imp.index, imp.values, color=[C2 if c in sum(GROUPS.values(), []) else C1 for c in imp.index])\\n",\n    "pct_axis(ax[0], 0, axis=\\"x\\"); ax[0].set(xlabel=\\"porsi total gain\\", title=\\"Kepentingan fitur (oranye = turunan)\\")\\n",\n    "der = derived(train, SHARE)\\n",\n    "grid = np.linspace(1.0, 1.4, 41)\\n",\n    "probe = X_final[TEST_LIKE].sample(2000, random_state=0).copy()\\n",\n    "pdp = []\\n",\n    "for g in grid:\\n",\n    "    probe[\\"markup\\"] = g\\n",\n    "    pdp.append(m.predict_proba(probe)[:, 1].mean())\\n",\n    "ax[1].plot(grid, pdp, color=C2)\\n",\n    "ax[1].axhline(THR, color=CN, ls=\\":\\", lw=1, label=f\\"ambang {THR:.2f}\\"); ax[1].legend()\\n",\n    "ax[1].set(xlabel=\\"rasio pengembalian (diset untuk semua baris)\\", ylabel=\\"rata-rata peluang gagal bayar\\", title=\\"Partial dependence rasio pengembalian\\")\\n",\n    "save_fig(FIG_DIR, \\"06_importance\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "e7fe76ae",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Rasio pengembalian menyumbang porsi gain terbesar, disusul bulan pencairan dan jenis pinjaman. Partial dependence menunjukkan peluang gagal bayar hampir nol sampai rasio sekitar 1,05, lalu naik tajam dan melewati ambang keputusan di kisaran rasio 1,1."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "dbf2429b",\n   "metadata": {},\n   "source": [\n    "### 8.2 Di mana model salah?"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "0e90040b",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "pred = (p_fin >= THR).astype(int)\\n",\n    "err = pd.DataFrame({\\"label\\": y, \\"pred\\": pred, \\"markup\\": der.markup, \\"status\\": train.status_peminjam, \\"jenis\\": train.jenis_pinjaman,\\n",\n    "                    \\"total kosong\\": ~TEST_LIKE})\\n",\n    "err[\\"jenis kesalahan\\"] = np.select([(err.label == 1) & (err.pred == 0), (err.label == 0) & (err.pred == 1)], [\\"gagal bayar terlewat\\", \\"alarm palsu\\"], \\"benar\\")\\n",\n    "tab = err[err[\\"jenis kesalahan\\"] != \\"benar\\"].groupby(\\"jenis kesalahan\\").agg(jumlah=(\\"label\\", \\"size\\"), median_rasio=(\\"markup\\", \\"median\\"),\\n",\n    "        porsi_total_kosong=(\\"total kosong\\", \\"mean\\"), porsi_peminjam_baru=(\\"status\\", lambda s: (s == \\"Peminjam_Baru\\").mean()))\\n",\n    "fig, ax = plt.subplots(figsize=(10, 4.3))\\n",\n    "for k, col, lab in [(\\"benar\\", CN, \\"benar\\"), (\\"gagal bayar terlewat\\", C2, \\"gagal bayar terlewat\\"), (\\"alarm palsu\\", C1, \\"alarm palsu\\")]:\\n",\n    "    s = err.markup[err[\\"jenis kesalahan\\"] == k].dropna().clip(0.95, 1.6)\\n",\n    "    ax.hist(s, bins=60, alpha=0.6, density=True, color=col, label=f\\"{lab} (n={len(s):,})\\")\\n",\n    "ax.set(yscale=\\"log\\", xlabel=\\"rasio pengembalian\\", ylabel=\\"densitas (log)\\", title=\\"Rasio pengembalian menurut hasil prediksi\\"); ax.legend()\\n",\n    "save_fig(FIG_DIR, \\"07_errors\\")\\n",\n    "tab.style.format({\\"median_rasio\\": \\"{:.3f}\\", \\"porsi_total_kosong\\": \\"{:.0%}\\", \\"porsi_peminjam_baru\\": \\"{:.0%}\\"})"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "b57c93f2",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Kesalahan terbagi hampir seimbang: 133 gagal bayar terlewat dan 116 alarm palsu. **41% gagal bayar yang terlewat adalah baris yang total pengembaliannya kosong**, sehingga rasio tidak bisa dihitung. Gagal bayar terlewat lainnya punya rasio rendah (median 1,061), sedangkan alarm palsu adalah pinjaman lancar dengan rasio tinggi (median 1,131). Keduanya ada di wilayah tumpang tindih rasio 1,05–1,2."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "0c7812c8",\n   "metadata": {},\n   "source": [\n    "## 9. Submission\\n",\n    "\\n",\n    "Model akhir dilatih ulang pada seluruh data latih dengan 5 seed, lalu probabilitas rata-ratanya diubah menjadi label dengan ambang dari bagian 7."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "fb6712c5",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "X_test = build(Xb_te, test, SHARE, KEEP)\\n",\n    "p_test = np.mean([lgb_model(s).fit(X_final, y).predict_proba(X_test)[:, 1] for s in SEEDS], axis=0)\\n",\n    "sub = sample[[ID]].merge(pd.DataFrame({ID: test[ID], TARGET: (p_test >= THR).astype(int)}), on=ID, how=\\"left\\")\\n",\n    "assert sub[TARGET].notna().all() and len(sub) == len(sample)\\n",\n    "sub.to_csv(OUT_DIR / \\"submission.csv\\", index=False)\\n",\n    "res = pd.DataFrame(RESULTS).T.sort_values(\\"macro F1 (seperti test)\\")\\n",\n    "res.to_csv(OUT_DIR / \\"cv_results.csv\\"); abl.to_csv(OUT_DIR / \\"ablation.csv\\", index=False)\\n",\n    "print(f\\"Ambang {THR:.2f} | prediksi gagal bayar di test: {sub[TARGET].mean():.2%} (train {y.mean():.2%})\\")\\n",\n    "res.style.format({c: \\"{:.4f}\\" for c in res.columns if c != \\"ambang\\"} | {\\"ambang\\": \\"{:.2f}\\"})"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "7addca07",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Proporsi prediksi gagal bayar di test 5,3%, dekat dengan 5,03% di train, sehingga ambang dari OOF terlihat cocok untuk test."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "5a329b46",\n   "metadata": {},\n   "source": [\n    "## 10. Kesimpulan\\n",\n    "\\n",\n    "1. **Satu rasio menjelaskan hampir semuanya.** Total pengembalian dibagi pokok menaikkan macro F1 dari 0,851 ke 0,940; atribut profil peminjam hampir tidak berperan.\\n",\n    "2. **Validasi harus meniru test.** Nilai kosong 10 kali lebih banyak di train, sehingga skor dihitung pada baris yang lengkap. Tanpa itu, skor CV meremehkan skor test sekitar 0,015.\\n",\n    "3. **Hasil.** Macro F1 OOF 0,947, late submission private 0,9450, sedikit di bawah submission tim terbaik saat kompetisi (0,9471) dan 0,016 di bawah peringkat 1 (0,9614).\\n",\n    "\\n",\n    "**Keterbatasan.** Total pengembalian kemungkinan dicatat setelah pinjaman berjalan, sehingga model ini lebih tepat disebut deteksi gagal bayar daripada credit scoring saat pengajuan. Tanpa atribut itu, macro F1 turun ke 0,667 (bagian 6.2), sehingga model untuk keputusan pemberian pinjaman butuh data peminjam yang lebih kaya.\\n",\n    "\\n",\n    "### Jejak lingkungan"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "50693d5c",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "import platform\\n",\n    "pkgs = [\\"numpy\\", \\"pandas\\", \\"scikit-learn\\", \\"lightgbm\\", \\"matplotlib\\", \\"seaborn\\"]\\n",\n    "print(\\" | \\".join([f\\"python {platform.python_version()}\\"] + [f\\"{p} {version(p)}\\" for p in pkgs]))\\n",\n    "print(f\\"Waktu eksekusi total: {(time.time() - T0) / 60:.1f} menit\\")"\n   ]\n  }\n ],\n "metadata": {\n  "kernelspec": {\n   "display_name": "Python 3",\n   "language": "python",\n   "name": "python3"\n  },\n  "language_info": {\n   "name": "python",\n   "version": "3.11"\n  }\n },\n "nbformat": 4,\n "nbformat_minor": 5\n}')

